  const a85Text=__AI_CONVERSATION_TEXTS__,a85Brand=__AI_CONVERSATION_BRAND__;
  const a85SendGlyph='<svg viewBox="0 0 24 24" aria-hidden="true" style="fill:currentColor;stroke:none"><path d="M2 21l21-9L2 3v7l15 2-15 2z"/></svg>';
  Object.assign(state,{a85Scene:'history',a85Draft:'',a85Messages:[],a85Busy:false,a85Undone:false,a85Activity:false,a85BillLedger:null});
  const a85Fields=()=>[['billCardAmount','US$12.00'],['billCardCategory','餐饮 / 午餐'],['billCardTime','今天 12:30'],['billCardType','支出'],['billCardCurrency','USD'],['billCardNote','QA 合成午餐'],['billCardAccount','美元账户']];
  function a85Bill(){const t=a85Text;return `<section class="bc-surface a85-bill"><div class="a85-bill-title">${icon(state.a85Undone?'circle-x':'circle-check')}<b>${esc(t[state.a85Undone?'billCardUndone':'billCardSuccess'])}</b></div>${btn('a85-ledger',`${icon('book-open')}${esc(state.a85BillLedger||state.ledger)}`,t.aiChatEmptyCurrentLedger,'a85-ledger',state.a85Undone?'disabled':'')}${a85Fields().map(([key,value])=>`<div class="a85-field"><span>${esc(t[key])}</span><b>${esc(value)}</b></div>`).join('')}<p class="bc-small">${esc(t.billCardTags)}</p><div>${tag('工作日')} ${tag('出差')}</div>${!state.a85Undone?`<div class="a85-bill-actions">${btn('a85-undo',esc(t.billCardUndo),t.billCardUndo,'bc-secondary')}${btn('page:editor',esc(t.billCardEdit),t.billCardEdit,'bc-secondary')}</div>`:''}</section>`;}
  function a85Authorization(){const t=a85Text;return `<div class="a85-authorization"><b>从文本记账</b><p>根据你输入的金额、用途和账户创建账单。</p><p>${esc(t.agentAuthorizationCurrentLedger.replace('{ledgerId}','1'))}</p><b>${esc(t.agentAuthorizationParameters)}</b><p class="bc-small">sourceText</p><pre>午餐花了32元，使用微信，标签工作日</pre></div><div class="a85-stacked-actions">${[['deny','agentAuthorizationDeny'],['once','agentAuthorizationAllowOnce'],['always','agentAuthorizationAlwaysAllow']].map(([value,key])=>btn('a85-authorize:'+value,esc(t[key]),t[key],value==='always'?'bc-primary':'bc-secondary')).join('')}</div>`;}
  function a85Conversation(){const t=a85Text,empty=['empty','first'].includes(state.a85Scene),first=state.a85Scene==='first',bill=['bill','undone'].includes(state.a85Scene),warning=state.a85Scene==='unconfigured',busy=state.a85Busy||state.a85Scene==='streaming';return `<div class="a85-layout"><header class="a85-header">${btn('page:home',icon('chevron-left'),t.commonBack)}<h2>${esc(t.aiChatTitle)}</h2>${btn('f-go:assistant-settings',icon('sliders-horizontal'),t.agentAssistantSettingsTitle)}${btn('a85-clear',icon('trash-2'),t.aiChatClearHistory)}</header>${warning?surface(`<p class="a85-warning">${esc(t.aiChatConfigWarning)}</p>${btn('f-go:ai-settings',esc(t.aiChatGoToSettings),t.aiChatGoToSettings,'bc-secondary')}`,'a85-notice'):''}<div class="a85-messages">${empty?`<div class="a85-empty">${first?'':'<p class="a85-period">2026年10月 · 当前账本</p>'}<span class="bc-avatar">${a85Brand}</span><h3>${esc(t[first?'aiChatEmptyFirstTransactionTitle':'aiChatEmptyStartTitle'])}</h3><p>${esc(t[first?'aiChatEmptyFirstTransactionDescription':'aiChatEmptyStartDescription'])}</p>${first?'':`<div class="a85-empty-metrics"><span><b>¥3,506.76</b><small>${esc(t.aiChatEmptyMonthExpense)}</small></span><span><b>41 笔</b><small>${esc(t.aiChatEmptyRecordedTransactions)}</small></span></div>`}<p class="a85-example">${esc(t[first?'aiChatEmptyFirstTransactionExample':'aiChatEmptyQuestionExample'])}</p></div>`:`<div class="bc-message-user">${esc(bill?'午餐花了12美元，使用美元账户。':'看看本月的收支情况。')}</div>${bill?a85Bill():surface(`<details class="a85-activity" ${state.a85Activity?'open':''}><summary>${busy?'正在查询账本…':'已完成 1 项操作'}</summary><p>收支概览 · 当前账本 · 本月</p><p>查询成功</p></details><div class="bc-chat-answer">${esc(state.a85Scene==='error'?'本次请求失败，请检查服务商配置后重试。':busy?'本月支出':'本月支出 ¥3,506.76。可以继续查看分类占比或预算。')}</div><div class="a85-answer-actions">${btn('a85-copy',icon('copy'),t.aiChatCopy)}${btn('a85-more',icon('ellipsis'),t.commonMore)}</div>`)}${!bill&&!busy?`<div class="a85-follow-ups">${btn('a85-suggest','本月哪类支出最多？','本月哪类支出最多？','bc-secondary')}${btn('a85-suggest','查看最近六个月趋势','查看最近六个月趋势','bc-secondary')}</div>`:''}`}${state.a85Messages.map(m=>`<div class="bc-message-user">${esc(m)}</div>${surface('<p class="bc-chat-answer">HTML 合成回复 · 不请求模型，也不创建真实账单。</p>')}`).join('')}</div><form class="a85-composer"><textarea rows="1" aria-label="${esc(t.aiChatInputHint)}" placeholder="${esc(t.aiChatInputHint)}" ${busy?'disabled':''}>${esc(state.a85Draft)}</textarea>${btn(busy?'a85-stop':'a85-send',(busy?icon('circle-stop'):a85SendGlyph),busy?t.agentRunStop:t.v4AIChatSend,'a85-send')}</form></div>`;}
  ai=a85Conversation;
  for(const[key,title]of [['chat-empty','空对话与真实账本摘要'],['chat-first','首笔记账空态'],['chat-history','AI对话与消息'],['chat-unconfigured','AI对话 · 未配置'],['chat-streaming','AI对话 · 流式与停止'],['chat-error','AI对话 · 请求失败'],['chat-bill','AI对话 · 外币账单卡'],['chat-undone','AI对话 · 已撤销账单']])fDefine(key,title,'AI与助手','ai/ai_chat_page.dart',a85Conversation);
  for(const[key,title]of [['chat-authorization',a85Text.agentAuthorizationTitle],['chat-clear',a85Text.aiChatClearHistoryDialogTitle],['chat-message-menu','消息操作'],['chat-delete',a85Text.commonDelete],['chat-ledger','账单所属账本']]){rSpecs[key]={title,host:'ai',kind:'dialog'};fDefine(key,title,'AI与助手','ai/ai_chat_page.dart',a85Conversation);}
  const a85Render=fRender;fRender=function(key){if(key.startsWith('chat-')){if(!state.rModal&&state.a85Preset!==key){state.a85Scene=key.slice(5);state.a85Preset=key;state.a85Busy=false;state.a85Undone=key==='chat-undone';state.a85Messages=[];}return a85Conversation();}return a85Render(key);};
  const a85Modal=rModalBody;rModalBody=function(key){if(key==='chat-authorization')return a85Authorization();if(key==='chat-clear'||key==='chat-delete')return `<p>${esc(a85Text[key==='chat-clear'?'aiChatClearHistoryDialogContent':'aiChatDeleteMessageConfirm'])}</p><div class="r-dialog-actions">${btn('r-close',esc(a85Text.commonCancel),a85Text.commonCancel,'bc-secondary')}${btn('a85-confirm:'+key,esc(a85Text.commonConfirm),a85Text.commonConfirm,'bc-primary')}</div>`;if(key==='chat-ledger')return `<p class="bc-small">只更改此账单所属账本，当前对话账本保持。</p>${['日常生活','家庭账本'].map(name=>btn('a85-bill-ledger:'+name,esc(name),name,'bc-secondary')).join('')}`;if(key==='chat-message-menu')return `<div class="a85-stacked-actions">${btn('a85-copy',icon('copy')+esc(a85Text.aiChatCopy),a85Text.aiChatCopy,'bc-secondary')}${btn('a85-delete',icon('trash-2')+esc(a85Text.commonDelete),a85Text.commonDelete,'bc-secondary')}</div>`;return a85Modal(key);};
  root.addEventListener('input',e=>{if(e.target.matches('.a85-composer textarea'))state.a85Draft=e.target.value;});
  root.addEventListener('submit',e=>{if(e.target.matches('.a85-composer')){e.preventDefault();a85Send();}});
  function a85Send(){const text=state.a85Draft.trim();if(!text||state.a85Busy)return;state.a85Messages.push(text);state.a85Draft='';render();phone.querySelector('.a85-messages')?.scrollTo(0,100000);}
  root.addEventListener('click',e=>{const el=e.target.closest('[data-action^="a85-"]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();const[a,value]=el.dataset.action.split(':');if(a==='a85-clear')rOpenModal('chat-clear');else if(a==='a85-send')a85Send();else if(a==='a85-stop'){state.a85Busy=false;state.a85Scene='history';render();notice(a85Text.agentRunStop);}else if(a==='a85-undo'){state.a85Undone=true;render();notice('HTML 示例撤销，不修改真实交易');}else if(a==='a85-ledger')rOpenModal('chat-ledger');else if(a==='a85-bill-ledger'){state.a85BillLedger=value;rDismiss();state.a85Scene='bill';render();}else if(a==='a85-more'){const rect=phone.getBoundingClientRect(),anchor=el.getBoundingClientRect(),factor=phone.clientWidth/rect.width;state.a85Anchor={x:(anchor.right-rect.left)*factor,y:(anchor.top-rect.top)*factor};rOpenModal('chat-message-menu');}else if(a==='a85-delete')rOpenModal('chat-delete');else if(a==='a85-copy'){rDismiss();render();notice('HTML 示例复制，未改写系统剪贴板');}else if(a==='a85-authorize'){rDismiss();render();notice('HTML 授权选择：'+value+' · 不执行工具');}else if(a==='a85-confirm'){state.a85Messages=[];state.a85Scene='empty';rDismiss();render();}else if(a==='a85-suggest'){state.a85Draft=el.textContent.trim();a85Send();}},true);

  const a85BuildModal=rBuildModal;rBuildModal=function(){a85BuildModal();if(state.rModal!=='chat-message-menu')return;const layer=phone.querySelector('.r-modal-layer'),panel=layer?.querySelector('.bc-sheet');if(!panel)return;layer.classList.add('a85-menu-layer');const a=state.a85Anchor||{x:90,y:340};panel.style.left=Math.min(Math.max(8,a.x),phone.clientWidth-120)+'px';panel.style.top=Math.min(Math.max(60,a.y),phone.clientHeight-140)+'px';};
  root.addEventListener('contextmenu',e=>{if(!e.target.closest('.a85-messages .bc-message-user,.a85-messages .bc-chat-answer'))return;e.preventDefault();const rect=phone.getBoundingClientRect(),factor=phone.clientWidth/rect.width;state.a85Anchor={x:(e.clientX-rect.left)*factor,y:(e.clientY-rect.top)*factor};rOpenModal('chat-message-menu');});
